/**
 * Find an assertion in a manifest by its label.
 *
 * `Assertions` is a flat array of `{ label, data }`
 *
 * @param {object} manifest The active C2PA manifest.
 * @param {string} label Assertion label, in reverse domain format.
 * @returns {object|undefined} The assertion's `data`, if the assertion exists.
 */
const getAssertionData = (manifest, label) => (manifest?.assertions ?? [])
  .find((assertion) => assertion.label === label)?.data;

/**
 * CAWG verified identities, from the decoded `cawg.identity` assertion.
 *
 * The SDK decodes that assertion in place while reading, so its data is the identity
 * claims aggregation credential itself, with `verifiedIdentities` at the top level.
 *
 * @param {object} manifest The active C2PA manifest.
 * @returns {object[]} Verified identities, or an empty array.
 */
const getVerifiedIdentities = (manifest) => {
  const identities = getAssertionData(manifest, 'cawg.identity')?.verifiedIdentities;
  return Array.isArray(identities) ? identities.filter(Boolean) : [];
};

/**
 * Parse a claim generator string into a human-readable one, e.g.
 * `Adobe_Photoshop/23.3.1` becomes `Adobe Photoshop 23.3.1`.
 *
 * Ported from the legacy c2pa SDK's `parseGenerator`.
 *
 * @param {string} value The claim generator / software agent string.
 * @returns {string} The formatted generator string.
 */
const parseGenerator = (value) => {
  // Strip parentheses so that any version inside them does not influence the test below.
  let withoutParens = '';
  let depth = 0;
  [...value].forEach((character) => {
    if (character === '(') {
      depth += 1;
    } else if (character === ')') {
      depth -= 1;
    } else if (depth === 0) {
      withoutParens += character;
    }
  });

  // Old-style (XMP Agent) string: matches space + version.
  if (/\s+\d+\.\d(\.\d)*\s+/.test(withoutParens)) {
    return value.split('(')[0]?.trim();
  }

  // User-Agent string. The RFC uses a space as the separator, and `product/version`
  // within each item.
  const [product, version] = (withoutParens.split(/\s+/)?.[0] ?? '').split('/');
  const formattedProduct = product.replace(/_/g, ' ');

  return version ? `${formattedProduct} ${version}` : formattedProduct;
};

/**
 * The tool that recorded the credentials, e.g. "Adobe Content Authenticity".
 *
 * Prefer the first named claim generator info entry, and fall back to parsing the
 * claim generator string.
 *
 * @param {object} manifest The active C2PA manifest.
 * @returns {string|null}
 */
const getRecordedBy = (manifest) => {
  const claimGeneratorInfo = manifest?.claim_generator_info;
  const generatorName = (Array.isArray(claimGeneratorInfo) ? claimGeneratorInfo : [])
    .find((info) => info?.name)?.name;
  if (generatorName) return generatorName;

  return manifest?.claim_generator ? parseGenerator(manifest.claim_generator) : null;
};

/**
 * The brand icon for a provider, or undefined when none of the patterns match.
 *
 * @param {string} provider Provider identifier, usually its URL.
 * @returns {{pattern: RegExp, label: string, svg: string}|undefined}
 */
const getProviderIcon = (provider) => (provider
  ? PROVIDER_ICONS.find(({ pattern }) => pattern.test(provider))
  : undefined);

/**
 * Display name for a provider that has no brand icon.
 *
 * The name is used exactly as entered in the credential data.
 * CreativeWork authors carry no name at all, so their account URL's host stands in.
 *
 * @param {{providerName: string, url: string|null}} account A social account.
 * @returns {string} The label, or an empty string when neither source is usable.
 */
const getProviderLabel = ({ providerName, url }) => {
  if (providerName) return providerName;

  const safeUrl = toSafeHttpUrl(url);
  return safeUrl ? new URL(safeUrl).hostname.replace(/^www\./, '') : '';
};

/**
 * Namespace an icon's internal ids so that repeating it across the page cannot produce
 * duplicate ids or cross-wired `url(#…)` references between popovers.
 *
 * @param {string} svg The icon markup.
 * @param {string} uid Unique suffix for this popover.
 * @returns {string} The icon markup with its ids suffixed.
 */
const withNamespacedIds = (svg, uid) => svg
  .replace(/id="([^"]+)"/g, `id="$1-${uid}"`)
  .replace(/url\(#([^)]+)\)/g, `url(#$1-${uid})`);

/**
 * Reduce a manifest to the values the CR pin popover displays.
 *
 * @param {object} manifest The active C2PA manifest.
 * @returns {{
 *   recordedBy: string|null,
 *   authorName: string|null,
 *   authorUrl: string|null,
 *   nameIsVerified: boolean,
 *   socialAccounts: {
 *     provider: string, providerName: string, url: string|null,
 *     username: string, verified: boolean,
 *   }[],
 *   doNotTrain: boolean,
 * }}
 */
const getManifestSummaryData = (manifest) => {
  const verifiedIdentities = getVerifiedIdentities(manifest);

  // Authors on the schema.org CreativeWork assertion. Those carrying an `@id` are
  // social accounts; the one without it is the producer. The assertion is signed but
  // otherwise unconstrained, so only trust entries that are actually objects.
  const authored = getAssertionData(manifest, 'stds.schema-org.CreativeWork')?.author;
  const authors = (Array.isArray(authored) ? authored : [])
    .filter((author) => author && typeof author === 'object');
  const producer = authors.find((author) => !('@id' in author)) ?? null;

  // A CAWG document verification supersedes the CreativeWork producer.
  const verifiedName = verifiedIdentities
    .find((identity) => identity.type === 'cawg.document_verification');

  // Verified social accounts replace the CreativeWork ones outright; they are not merged.
  const verifiedSocialAccounts = verifiedIdentities
    .filter((identity) => identity.type === 'cawg.social_media')
    .map((identity) => ({
      provider: identity.provider?.id ?? '',
      providerName: identity.provider?.name ?? '',
      url: identity.uri ?? null,
      username: identity.username,
      verified: true,
    }));
  const authoredSocialAccounts = authors
    .filter((author) => '@id' in author)
    .map((author) => ({
      provider: author['@id'] ?? '',
      // CreativeWork authors carry no provider name; the render falls back to the host.
      providerName: '',
      url: author['@id'] ?? null,
      username: author.name,
      verified: false,
    }));

  // The opt-out is recorded on either the CAWG or the C2PA training/mining assertion.
  const entries = getAssertionData(manifest, 'cawg.training-mining')?.entries
    ?? getAssertionData(manifest, 'c2pa.training-mining')?.entries
    ?? {};

  return {
    recordedBy: getRecordedBy(manifest),
    authorName: verifiedName?.name ?? producer?.name ?? null,
    // Profile the verifying provider vouched for. Only a CAWG document verification
    // carries one; a CreativeWork producer has no URI.
    authorUrl: verifiedName?.uri ?? null,
    // Only a CAWG document verification is vouched for; a CreativeWork producer is not.
    nameIsVerified: Boolean(verifiedName?.name),
    socialAccounts: verifiedSocialAccounts.length
      ? verifiedSocialAccounts
      : authoredSocialAccounts,
    doNotTrain: TRAINING_MINING_ENTRY_KEYS
      .some((key) => TRAINING_MINING_NOT_ALLOWED.includes(entries[key]?.use)),
  };
};

/**
/**
 * Whether a pin's panel is open. `aria-expanded` is the single source of truth, so what
 * assistive tech is told and what the page shows cannot drift apart.
 *
 * @param {HTMLButtonElement} button A CR pin button.
 * @returns {boolean}
 */
const isPinOpen = (button) => button.getAttribute('aria-expanded') === 'true';

/**
 * Open or close one pin's panel.
 *
 * @param {HTMLButtonElement} button The pin button controlling the panel.
 * @param {boolean} open Whether the panel should end up open.
 * @param {object} [options]
 * @param {boolean} [options.moveFocus=false] Move focus into the panel on open. Only
 * deliberate activation does this — a panel revealed by hover must not take focus away
 * from wherever the visitor left it.
 * @param {boolean} [options.restoreFocus=false] Move focus back to the button on close.
 * Used for Escape; not for an outside click, which has already placed focus deliberately.
 */
const setPinOpen = (button, open, { moveFocus = false, restoreFocus = false } = {}) => {
  const panel = document.getElementById(button.getAttribute('aria-controls'));
  if (!panel) return;

  // Cleared on every transition. The hover handler sets it again straight afterwards, so
  // a panel that is opened, or committed, by any other route is no longer hover-owned.
  delete button.dataset.crHoverOpen;
  button.setAttribute('aria-expanded', open ? 'true' : 'false');
  panel.hidden = !open;

  // A dialog role leads assistive tech to expect focus to follow it. On close, focus is
  // pulled back whenever it sits inside the panel, so it is never left on hidden content.
  if (open && moveFocus) panel.focus();
  else if (!open && (restoreFocus || panel.contains(document.activeElement))) button.focus();
};

/**
 * Close every open pin on the page.
 *
 * @param {HTMLButtonElement} [except] Pin to leave alone.
 * @param {boolean} [restoreFocus=false] Passed through to {@link setPinOpen}.
 */
const closeAllPins = (except, restoreFocus = false) => {
  document.querySelectorAll('.cr-pin-button[aria-expanded="true"]').forEach((button) => {
    if (button !== except) setPinOpen(button, false, { restoreFocus });
  });
};

/**
 * Grace period before a hover-revealed panel closes, so the pointer can travel from the
 * pin to the panel across the gap between them.
 */
const HOVER_CLOSE_DELAY_MS = 500;

/**
 * Whether {@link bindPinDismissal} has already run.
 */
let pinDismissalBound = false;

/**
 * Bind the dismiss behaviour the Popover API used to provide. One pair of listeners for
 * the page rather than a pair per pin, since an article can carry many credentialed
 * images, and only ever bound once however often this module is initialised.
 */
const bindPinDismissal = () => {
  if (pinDismissalBound) return;
  pinDismissalBound = true;

  document.addEventListener('click', (event) => {
    if (!event.target.closest('.cr-pin-image')) closeAllPins();
  });

  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') closeAllPins(undefined, true);
  });
};

/**
 * Adds a "CR" pin button to the image's pin wrapper. The button toggles a panel that
 * displays the image's content credentials data and an inspect button.

 * @param {HTMLElement} pinWrapper The wrapper element to append the button to.
 * @param {object} manifest The image's active C2PA manifest.
 * @param {string} sourceUrl The image's original URL, handed to Verify for inspection.
 */
const buildCRPinPopoverComponent = (pinWrapper, manifest, sourceUrl) => {
  const popoverId = `cr-popover-${crypto.randomUUID()}`;
  const groupClass = 'cr-pin-popover__group';
  const itemClass = 'cr-pin-popover__item';

  const headingId = `${popoverId}-heading`;

  // CR pin button that toggles the popover.
  const button = document.createElement('button');
  button.type = 'button';
  button.classList.add('cr-pin-button');
  button.setAttribute('aria-label', 'View content credentials for this image');
  button.setAttribute('aria-haspopup', 'dialog');
  button.setAttribute('aria-controls', popoverId);
  button.setAttribute('aria-expanded', 'false');
  button.innerHTML = CR_PIN_ICON;

  // Popover (container/content). Named by its own heading, and focusable so opening it
  // can move focus here, as a dialog role leads assistive tech to expect.
  const popover = document.createElement('div');
  popover.id = popoverId;
  popover.classList.add('cr-pin-popover');
  popover.setAttribute('role', 'dialog');
  popover.setAttribute('aria-labelledby', headingId);
  popover.tabIndex = -1;
  popover.hidden = true;
  popover.innerHTML = `<div class="cr-pin-popover__group"><h3 class="cr-pin-popover__heading" id="${headingId}">Content Credentials</h3></div>`;

  // Build groups of items based on the CR data in the manifest.
  // Manifest values are third-party data: always set them as text, never as markup.
  const {
    recordedBy, authorName, authorUrl, nameIsVerified, socialAccounts, doNotTrain,
  } = getManifestSummaryData(manifest);

  // The tool that recorded the credentials, alongside the heading.
  if (recordedBy) {
    const subheading = document.createElement('p');
    subheading.classList.add('cr-pin-popover__subheading');
    subheading.textContent = `Recorded by ${recordedBy}`;
    popover.firstElementChild.append(subheading);
  }

  /**
   * Group holding the name of the credential's author, linked to the verified profile
   * where the credential carries one, and followed by the verified badge when an
   * identity provider vouched for that name.
   *
   * @returns {HTMLElement|null} The group, or null when the manifest names no author.
   */
  const buildCredentialName = () => {
    if (!authorName) return null;

    const group = document.createElement('div');
    group.classList.add(groupClass);
    const item = document.createElement('div');
    item.classList.add(itemClass, `${itemClass}--name`);
    group.append(item);

    const label = document.createElement('span');
    label.classList.add('cr-pin-popover__label');
    label.textContent = 'Name ';

    // Link the name to the profile the verifier vouched for, where there is one, as the
    // legacy component does. Opening in a new tab follows this project's external-link
    // convention and keeps the popover from being navigated away.
    const profileUrl = toSafeHttpUrl(authorUrl);
    const nameText = document.createElement(profileUrl ? 'a' : 'span');
    nameText.classList.add('cr-pin-popover__author-name');
    nameText.textContent = authorName;
    if (profileUrl) {
      nameText.href = profileUrl;
      nameText.target = '_blank';
      nameText.rel = 'noopener noreferrer';
      nameText.setAttribute('aria-label', `${authorName} (opens in a new tab)`);
    }

    item.append(label, nameText);

    // The badge is only truthful for a name an identity provider vouched for.
    if (nameIsVerified) {
      const verifiedIcon = document.createElement('span');
      verifiedIcon.classList.add('cr-pin-popover__verified');
      verifiedIcon.innerHTML = VERIFIED_ICON;
      item.append(verifiedIcon);
    }

    return group;
  };

  /**
   * Group listing the author's connected social accounts. Each account links out when
   * its URL is a usable http(s) one, and is plain text otherwise.
   *
   * @returns {HTMLElement|null} The list, or null when there is no account to show.
   */
  const buildCredentialSocials = () => {
    if (!socialAccounts.length) return null;

    const list = document.createElement('ul');
    list.classList.add(groupClass, 'cr-pin-popover__socials');

    // Still have VoiceOver treat as a list, even though it uses `list-style: none`.
    list.setAttribute('role', 'list');

    // Append each social account, led by its brand icon.
    socialAccounts.forEach((account) => {
      const { username, url } = account;
      if (!username) return;

      const listItem = document.createElement('li');
      listItem.classList.add(itemClass, `${itemClass}--social`);
      const accountUrl = toSafeHttpUrl(url);

      // A recognised provider gets its brand icon; anything else falls back to the
      // provider's name, so the account is still attributed.
      const icon = getProviderIcon(account.provider);
      const platform = icon?.label || getProviderLabel(account);
      if (icon) {
        const iconWrapper = document.createElement('span');
        iconWrapper.classList.add('cr-pin-popover__social-icon');
        if (icon.invertOnDark) {
          iconWrapper.classList.add('cr-pin-popover__social-icon--invert-on-dark');
        }
        iconWrapper.innerHTML = withNamespacedIds(icon.svg, popoverId);
        listItem.append(iconWrapper);
      } else if (platform) {
        const labelText = document.createElement('span');
        labelText.classList.add('cr-pin-popover__label');
        labelText.textContent = platform;
        listItem.append(labelText);
      }

      // Opened in a new tab so the popover is not navigated away, matching both the
      // legacy component and this project's external-link convention. Appended rather
      // than assigned as text, so the icon or label already in the item survives.
      if (accountUrl) {
        const link = document.createElement('a');
        link.href = accountUrl;
        link.textContent = username;
        link.target = '_blank';
        link.rel = 'noopener noreferrer';
        // The platform is only conveyed by the icon beside the link, which is decorative,
        // so name it here too. Keeps the visible username inside the accessible name.
        const platformSuffix = platform ? ` on ${platform}` : '';
        link.setAttribute('aria-label', `${username}${platformSuffix} (opens in a new tab)`);
        listItem.append(link);
      } else {
        listItem.append(username);
      }

      list.append(listItem);
    });

    if (!list.children.length) return null;
    return list;
  };

  /**
   * Group holding the rights and usage notice: the author's opt-out of generative AI
   * training and use.
   *
   * @returns {HTMLElement|null} The group, or null when the author did not opt out.
   */
  const buildCredentialAiNotice = () => {
    if (!doNotTrain) return null;

    const group = document.createElement('div');
    group.classList.add(groupClass);
    const item = document.createElement('p');
    item.classList.add(itemClass, `${itemClass}--ai-notice`);
    group.append(item);

    const icon = document.createElement('span');
    icon.classList.add('cr-pin-popover__dnt');
    icon.innerHTML = DNT_ICON;

    const notice = document.createElement('span');
    notice.textContent = 'I request that generative AI models not train on or use my content.';
    item.append(icon, notice);

    return group;
  };

  /**
   * Link out to Content Authenticity Verify, where the full credentials can be
   * inspected. Always shown, since anything with a manifest can be inspected there.
   *
   * @returns {HTMLElement} The paragraph wrapping the link.
   */
  const buildInspectButton = () => {
    const paragraph = document.createElement('p');
    paragraph.classList.add(groupClass, 'cr-pin-popover__inspect');

    // Verify loads the image itself from a `source` parameter. Without it the visitor
    // lands on an empty Verify page and has to upload the image by hand.
    const inspectUrl = new URL(INSPECT_URL);
    const source = toSafeHttpUrl(sourceUrl);
    if (source) inspectUrl.searchParams.set('source', source);

    const link = document.createElement('a');
    link.classList.add('button', 'button--outline');
    link.href = inspectUrl.toString();
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.setAttribute('aria-label', 'Inspect (opens in a new tab)');
    link.append('Inspect');

    const icon = document.createElement('span');
    icon.classList.add('cr-pin-popover__inspect-icon');
    icon.innerHTML = INSPECT_ICON;
    link.append(icon);

    paragraph.append(link);

    return paragraph;
  };

  // Only append the groups that have something to show.
  popover.append(...[
    buildCredentialName(),
    buildCredentialSocials(),
    buildCredentialAiNotice(),
    buildInspectButton(),
  ].filter(Boolean));

  bindPinDismissal();

  // Hover reveals the panel, and only the pin and the panel itself count as hovered.
  // Closing is deferred by a beat so the pointer can cross the gap between the two;
  // WCAG 1.4.13 requires the revealed content to be reachable by pointer.
  let hoverCloseTimer = null;
  const cancelHoverClose = () => {
    window.clearTimeout(hoverCloseTimer);
    hoverCloseTimer = null;
  };

  // Mouse only: a touch tap also fires `pointerenter`, which would open the panel and
  // then have the click close it again.
  const onHoverEnter = (event) => {
    if (event.pointerType !== 'mouse') return;
    cancelHoverClose();
    if (isPinOpen(button)) return;
    closeAllPins(button);
    setPinOpen(button, true);
    button.dataset.crHoverOpen = 'true';
  };

  const onHoverLeave = (event) => {
    if (event.pointerType !== 'mouse' || button.dataset.crHoverOpen !== 'true') return;
    cancelHoverClose();
    hoverCloseTimer = window.setTimeout(() => {
      // Re-checked because a click may have committed the panel in the meantime.
      if (button.dataset.crHoverOpen === 'true') setPinOpen(button, false);
    }, HOVER_CLOSE_DELAY_MS);
  };

  [button, popover].forEach((element) => {
    element.addEventListener('pointerenter', onHoverEnter);
    element.addEventListener('pointerleave', onHoverLeave);
  });

  // Safari does not focus a button when it is clicked, so pressing the pin while its
  // panel is open blurs the panel to nowhere: `focusout` sees no related target, closes
  // the panel on mousedown, and the click that follows reads the panel as closed and
  // reopens it. Suppressing the default focus change leaves focus inside the wrapper,
  // where the click handler expects it — this component places focus itself anyway.
  button.addEventListener('mousedown', (event) => {
    event.preventDefault();
  });

  button.addEventListener('click', () => {
    // A hover-revealed panel is already open, so this click commits it rather than
    // closing it — otherwise clicking what you are pointing at would dismiss it.
    const committed = isPinOpen(button) && button.dataset.crHoverOpen !== 'true';
    if (committed) {
      setPinOpen(button, false);
      return;
    }
    closeAllPins(button);
    setPinOpen(button, true, { moveFocus: true });
  });

  // Non-modal, so focus is never trapped: leaving the panel by any route closes it.
  // Only this pin closes — focus moving to another pin's panel must not close that one.
  pinWrapper.addEventListener('focusout', (event) => {
    if (!pinWrapper.contains(event.relatedTarget)) setPinOpen(button, false);
  });

  // Append the CR pin and its popover.
  pinWrapper.append(button, popover);
};

/**
 * Find the page's matching images, read their CR data, and give every image that has a
 * manifest a wrapped `picture` carrying the CR pin and its popover. Images without
 * credentials are left untouched.
 *
 * @param {string} crImageSelector Selector matching the images to read.
 * @returns {Promise<void>} Resolves once every image has been read.
 */
const addContentCredentials = async (crImageSelector) => {
  // Get the image element(s) from the page. Bailing here is what keeps a page with no
  // candidate images from ever loading the c2pa bundle or its WASM.
  const images = document.querySelectorAll(crImageSelector);
  if (!images.length) {
    return;
  }

  // Find all relevant images in the DOM and read their credentials.
  // If there is CR data, give it a wrapper and add the pin with its data.
  // Awaited as a whole so the c2pa instance is not disposed while reads are in flight.
  await Promise.all([...images].map(async (img) => {
    // Get CR data.
    const activeManifest = await readCredentials(img);
    if (!activeManifest) return;

    // Give the picture element a wrapper, for positioning the CR pin on top of it.
    const picture = img.closest('picture');
    if (!picture) return;

    const crPinWrapper = document.createElement('span');
    crPinWrapper.classList.add('cr-pin-image');
    picture.before(crPinWrapper);
    crPinWrapper.append(picture);
    buildCRPinPopoverComponent(crPinWrapper, activeManifest, getOriginalImageUrl(img));
  }));
};

/**
 * Add content credentials to every relevant image on the page.
 *
 * Errors are caught so a failed read never breaks the page, and the c2pa instance is
 * always disposed of, releasing the worker and its WASM memory.
 *
 * @returns {Promise<void>} Resolves once the page has been processed.
 */
export default async function initContentCredentials() {
  try {
    await addContentCredentials(CR_IMAGE_SELECTORS);
  } catch (error) {
    /* eslint-disable-next-line no-console */
    console.error('Error reading C2PA data:', error);
  } finally {
    if (c2pa) {
      c2pa.dispose();
      c2pa = null;
    }
    // Cleared alongside the instance so a later call sets up a fresh one, rather than
    // resolving against the memoised promise for the disposed instance.
    c2paReady = null;
  }
}
